"""Validated, read-only provider profile support.

The profile is deliberately data-only and lives in /data.  It is populated only
after observing the official application's authorised read-only exchange.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from urllib.parse import urlsplit

PROFILE_PATH = Path("/data/md_parking_read_only_profile.json")
BLOCKED_WORDS = ("open", "close", "barrier", "gate", "control", "command", "action")


class ProfileError(ValueError):
    """The local provider profile is absent or violates the read-only boundary."""


@dataclass(frozen=True)
class RequestProfile:
    method: str
    url: str
    headers: dict[str, str]
    json_body: dict[str, object] | None = None


@dataclass(frozen=True)
class ReadOnlyProfile:
    auth: RequestProfile
    cameras: RequestProfile
    token_path: str
    items_path: str
    alias_path: str
    source_path: str


def _request(value: object, allowed_hosts: set[str]) -> RequestProfile:
    if not isinstance(value, dict):
        raise ProfileError("profile request must be an object")
    method = value.get("method")
    url = value.get("url")
    if method not in {"GET", "POST"} or not isinstance(url, str):
        raise ProfileError("only GET and POST HTTPS profile requests are allowed")
    parsed = urlsplit(url)
    if parsed.scheme != "https" or parsed.hostname not in allowed_hosts:
        raise ProfileError("profile URL host is not in the explicit allow-list")
    if any(word in parsed.path.lower() for word in BLOCKED_WORDS):
        raise ProfileError("profile contains a forbidden control-like path")
    headers = value.get("headers", {})
    body = value.get("json")
    if not isinstance(headers, dict) or (body is not None and not isinstance(body, dict)):
        raise ProfileError("profile headers and JSON body must be objects")
    return RequestProfile(method, url, {str(k): str(v) for k, v in headers.items()}, body)


def load_profile(path: Path = PROFILE_PATH) -> ReadOnlyProfile:
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ProfileError("verified local read-only profile has not been installed") from exc
    except json.JSONDecodeError as exc:
        raise ProfileError("local read-only profile is not valid JSON") from exc
    if raw.get("version") != 1:
        raise ProfileError("unsupported local profile version")
    hosts = raw.get("allowed_hosts")
    if not isinstance(hosts, list) or not hosts or not all(isinstance(host, str) for host in hosts):
        raise ProfileError("profile must declare non-empty allowed_hosts")
    strings = ("token_path", "items_path", "alias_path", "source_path")
    if not all(isinstance(raw.get(key), str) and raw[key] for key in strings):
        raise ProfileError("profile is missing one or more response paths")
    allowed_hosts = set(hosts)
    return ReadOnlyProfile(
        auth=_request(raw.get("auth"), allowed_hosts),
        cameras=_request(raw.get("cameras"), allowed_hosts),
        token_path=raw["token_path"],
        items_path=raw["items_path"],
        alias_path=raw["alias_path"],
        source_path=raw["source_path"],
    )
